for r in rows:
 if not r.get('changed'):continue
 p=pathlib.Path(r['path']);text=p.read_text(encoding='utf-8');old=text
 contract=C.get(r['name'])
 if r['name'].startswith('persona-') and not contract:
  contract='Use this optional Workspace role only for the specific requested operations. Planning/inspection/content creation does not authorize sends, Chat announcements, invitations, cloud publication or new schedules. Use actual existing records and AI OS domain homes. Model Armor --sanitize requires verified configured template/scopes and external-payload/cost authorization; it is not proof of local privacy protection.'
 if r['name'].startswith('higgsfield-'):
  contract='Use only when the user explicitly selects Higgsfield provider/workflow. Verify available credentials and authorized cost before media generation. Generic image/video/website requests do not select this provider. Preserve outputs; build preview separately from explicit authorized public deployment.'
 if contract:
  text=text.replace(r['contract'],contract,1);r['contract']=contract
 if r['name']=='recipe-create-doc-from-template':text=text.replace('--document-id','--document')
 if r['name']=='persona-exec-assistant':text=text.replace('gws gmail +send --to','gws gmail +send --draft --to')
 if text!=old:
  if p.read_text(encoding='utf-8')!=old:raise RuntimeError('Concurrent edit '+str(p))
  p.write_text(text,encoding='utf-8',newline='');r['after_sha256']=hashlib.sha256(p.read_bytes()).hexdigest()
